$ErrorActionPreference = 'Stop'

$embedded = @{
    'FireURQ-StreamSource-x86.bb744450ea6b4644af700bc15aebf245.ps1' = ''
    'FireURQ-D3D8TriangleOverlay.ps1' = ''
    'FireURQ-D3D8GeneratedSceneOverlay.ps1' = ''
    'FireURQ-D3D8RenderTextureOverlay.ps1' = ''
}

$runDir = Join-Path $env:TEMP ('FireURQ.RenderTexture.' + [Guid]::NewGuid().ToString('N'))
Push-Location -LiteralPath (Split-Path -Parent $PSScriptRoot)

try {
    Write-Host 'Generating fresh C# for the render texture probe...'
    $verification = @(powershell.exe -NoProfile -File .\Tools\VerifyGeneratedProject.ps1 -PreviousErrorCount 74 |
        ForEach-Object { Write-Host $_; $_ })

    $directoryLine = $verification |
        Where-Object { $_ -like 'Verification directory:*' } |
        Select-Object -First 1
    if (!$directoryLine) { throw 'Verification directory was not reported.' }

    $generated = Join-Path ($directoryLine -replace '^Verification directory:\s*', '') 'translation-output'
    $core = Join-Path $generated 'd2dge-furq_2_2_4\d2dCore.cs'
    $runtime = Join-Path $generated '__runtime\D3D8Adapter.cs'
    foreach ($file in @($core, $runtime)) {
        if (!(Test-Path -LiteralPath $file -PathType Leaf)) {
            throw "Fresh generated file is missing: $file"
        }
    }

    New-Item -ItemType Directory -Path $runDir | Out-Null
    foreach ($name in $embedded.Keys) {
        $path = Join-Path $runDir $name
        [IO.File]::WriteAllBytes($path, [Convert]::FromBase64String($embedded[$name]))

        if ($name -like 'FireURQ-StreamSource-x86.*.ps1') { continue }

        $source = [IO.File]::ReadAllText($path)
        $source = [regex]::Replace($source, '(?m)^[ \t]*/\*[^\r\n]*\*/[ \t]*$', '')
        $source = $source.Replace('$env:TEMP', '$fireurqProbeDirectory')
        [IO.File]::WriteAllText($path, $source, [Text.UTF8Encoding]::new($true))
    }

    # The embedded overlays expect these two historical path names.
    # Supply both from the C# generated by this invocation.
    $aliases = @(
        'FireURQ.ProjectVerification.5ed6fb2af5a343b3b78f61b755f92588'
        'FireURQ.ProjectVerification.b686768659794ecba5e08346cfa036ff'
    )
    foreach ($alias in $aliases) {
        $output = Join-Path $runDir "$alias\translation-output"
        New-Item -ItemType Directory -Path (Join-Path $output '__runtime') -Force | Out-Null
        New-Item -ItemType Directory -Path (Join-Path $output 'd2dge-furq_2_2_4') -Force | Out-Null
        Copy-Item -LiteralPath $runtime -Destination (Join-Path $output '__runtime')
        Copy-Item -LiteralPath $core -Destination (Join-Path $output 'd2dge-furq_2_2_4')
    }

    $fireurqProbeDirectory = $runDir
    & (Join-Path $runDir 'FireURQ-D3D8RenderTextureOverlay.ps1')
}
catch {
    $report = "STOP: $($_.Exception.GetBaseException().Message)"
    Write-Output $report
    Set-Clipboard -Value $report -ErrorAction Stop
    Write-Host 'RESULT COPIED'
}
finally {
    Pop-Location
    if (Test-Path -LiteralPath $runDir) {
        Remove-Item -LiteralPath $runDir -Recurse -Force
    }
}